from pathlib import Path
TODAY='2026-06-18'

def header(title): return f"# {title}\n\n> - 引用级别：✅可供学习参考\n> - 最后更新：{TODAY}\n\n"
def write(path,text): Path(path).write_text(text.strip()+"\n", encoding='utf-8')
def render(title,path,pos,concepts,asks,triage,combined,analysis):
    c='\n\n'.join(f"### {i+1}. {h}\n\n{b}" for i,(h,b) in enumerate(concepts))
    a='\n'.join(f"- {x}" for x in asks)
    t='\n'.join(f"| {x[0]} | {x[1]} | {x[2]} | {x[3]} |" for x in triage)
    cb='\n'.join(f"| {x[0]} | {x[1]} | {x[2]} | {x[3]} |" for x in combined)
    an='\n'.join(f"- **{k}：** {v}" for k,v in analysis)
    write(path, header(title)+f'''## 一句话定位\n\n{pos}\n\n## 一、准确解释：标题里的概念分别是什么\n\n{c}\n\n## 二、药店咨询首先要问什么\n\n{a}\n\n## 三、轻症、需药师判断、应就医的分层\n\n| 分层 | 典型表现 | 药店/平台可以做什么 | 不应做什么 |\n|---|---|---|---|\n{t}\n\n## 四、品类、咨询口径与即时零售场景\n\n| 品类/服务 | 对应场景 | 药师提醒点 | 平台/药店承接点 |\n|---|---|---|---|\n{cb}\n\n## 五、对平台、药店、药企的业务分析\n\n{an}\n''')

# High-quality rewrites for key concept-heavy docs
render('腹泻胃痛消化不良基础概念','08-疾病与医学基础/补充资料/腹泻胃痛消化不良基础概念.md',
'本文回答：腹泻、胃痛、消化不良这三个高频消化系统症状分别是什么，为什么用户会混在一起表达，以及药店和即时零售平台应如何把轻症对症、药师咨询和就医提醒分开。核心判断是：这类需求适合承接补液、对症用品、家庭常备和药师解释，但不能把“拉肚子”“胃痛”“不消化”等搜索词直接等同为某个疾病或某个药品。',
[('腹泻：核心是排便频次、粪便性状和脱水风险','腹泻不是一个单一疾病，而是一种排便表现，通常表现为排便次数增多、粪便变稀或水样便。它可能伴随腹痛、肠鸣、腹胀、恶心、呕吐、发热或乏力。常见诱因包括饮食不洁、胃肠道感染、食物不耐受、药物影响、肠易激综合征、炎症性肠病等。药店咨询里，腹泻最重要的不是马上推荐止泻药，而是先判断病程长短、脱水风险、是否发热、是否血便/黑便、是否儿童老人孕妇等高风险人群。'),('胃痛/上腹痛：用户说“胃痛”不等于一定是胃病','“胃痛”是用户口语，通常指上腹部疼痛、烧灼感、绞痛、胀痛、隐痛或餐前餐后不适。它可能来自胃酸反流、胃炎样不适、消化不良、胃肠痉挛，也可能与胆囊、胰腺、心血管问题或药物刺激有关。药店不能把“胃痛”直接翻译成“买胃药”，而要追问疼痛位置、持续时间、是否与进食相关、是否伴黑便呕血、胸痛出汗、体重下降或吞咽困难。'),('消化不良：是一组上腹部不适症状，不是明确诊断','消化不良通常包括餐后饱胀、早饱、上腹痛或烧灼感，也可能伴随嗳气、反酸、恶心、食欲下降。它可以是功能性消化不良，也可能与胃食管反流、胃炎、消化性溃疡、幽门螺杆菌感染、药物刺激或其他疾病有关。用户说“不消化”“胃胀”“吃撑了”，不代表一定适合助消化药，也不代表没有需要评估的基础病。'),('三者的关系：经常同时出现，但咨询逻辑不同','腹泻、胃痛和消化不良都属于消化系统高频症状，用户常组合表达为“吃坏肚子胃痛”“拉肚子胃胀”“反酸不消化”。但腹泻先看脱水和感染风险，胃痛先看疼痛部位和严重程度，消化不良先看餐后关系、反复程度和报警症状。专业文章必须把症状识别、对症用品、药师咨询和就医提醒拆开。')],
['症状是哪一个为主：水样便/次数增多、上腹痛，还是餐后饱胀早饱反酸。','持续多久、每天几次、是否越来越重，是否影响进食饮水和睡眠。','是否有发热、呕吐、血便、黑便、严重脱水、持续剧痛、呕血、胸痛、体重下降或吞咽困难。','是否儿童、老人、孕妇、免疫低下或有慢性胃肠病史。','近期是否有不洁饮食、旅行、抗生素、止痛药、饮酒或已经使用胃肠药。'],
[('轻症自我管理','短期、轻度、无血便黑便、无严重脱水和持续剧痛','补液、说明书教育、药师咨询、短期观察','不做疾病诊断，不承诺快速治愈'),('药师重点判断','反复、持续、儿童老人、伴发热呕吐或近期抗生素/止痛药使用','追问病程、风险因素、用药禁忌和重复成分，必要时建议就医','不直接推荐多药叠加或强行压住症状'),('优先就医','血便、黑便、呕血、严重脱水、持续剧痛、高热、意识差、胸痛出汗','明确提示就医或急诊评估','不引导仅靠自购药处理')],
[('口服补液盐','腹泻、呕吐后补液；夜间急用；儿童老人家庭常备','按说明书配制，关注脱水、尿量、精神状态','附近库存、家庭常备清单、儿童老人提示'),('止泻相关药物','短期轻症、无红旗信号的腹泻咨询','发热、血便、疑似感染、儿童老人孕妇需谨慎','药师在线问询后再展示，不做默认首推'),('益生菌','部分腹泻、抗生素后肠道不适或家庭常备','不夸大疗效，免疫低下人群需谨慎','常备补货、说明书教育'),('胃酸相关OTC','反酸、烧心、短期上腹不适','黑便、呕血、吞咽困难、持续疼痛、年龄风险需就医','按症状词分流，不把所有胃痛导向同一商品'),('助消化/消化酶类','餐后饱胀、饮食相关不适','不替代持续或反复症状评估','与饮食提醒、药师咨询一起展示'),('就医提醒服务','红旗信号或特殊人群','明确提示线下就医','平台拦截高风险搜索，不以转化为先')],
[('平台','消化症状入口要先区分腹泻、胃痛和消化不良，再做商品展示；红旗信号应触发就医提醒。'),('药店','药师问询应围绕脱水、血便黑便、疼痛部位、病程和既往用药，而不是直接推荐胃肠药。'),('药企','适合做成分区分、适用人群和说明书教育，不能把症状营销等同疾病诊断。')])

render('感冒与流感基础概念','08-疾病与医学基础/补充资料/感冒与流感基础概念.md',
'本文回答：普通感冒、流感以及其他呼吸道感染为什么不能混写，用户在发热、咳嗽、咽痛和鼻塞场景中应如何分层。核心判断是：普通感冒多为自限性上呼吸道感染，流感起病更急、全身症状更重，高风险人群需要更早识别；平台不能把“感冒药”搜索直接导向复方感冒药。',
[('普通感冒：多为上呼吸道病毒感染，重点是对症支持','普通感冒通常逐渐出现鼻塞、流涕、打喷嚏、咽痛、轻咳、低热或乏力。它多数是病毒感染，抗生素通常不适用。药店服务重点是帮助用户识别轻症、避免重复复方感冒药、提醒休息补液和说明书边界。'),('流感：起病急、全身症状重，高风险人群更需要警惕','流感常突然出现高热或畏寒、肌肉酸痛、头痛、明显乏力、咳嗽和咽痛。儿童可能伴呕吐腹泻。老人、儿童、孕妇、慢病患者和免疫低下人群发生并发症风险更高，不能简单当普通感冒处理。'),('其他呼吸道感染：症状重叠，不能靠关键词判断','新冠、肺炎、鼻窦炎、过敏性鼻炎、哮喘/COPD急性加重都可能出现咳嗽、咽痛或发热。平台和药店不能仅凭“感冒”“咳嗽”搜索词判断病因。'),('复方感冒药：最常见风险是重复成分和特殊人群误用','复方感冒药可能含退热镇痛、抗组胺、减充血、镇咳等成分。多个复方药叠加容易造成超量。儿童、老人、孕妇、高血压、肝病、青光眼、前列腺增生等人群用药更需谨慎。')],
['起病是突然还是逐渐，发热多少度，是否全身酸痛和明显乏力。','是否呼吸困难、胸痛、意识异常、持续高热、血氧下降或咳血。','是否儿童、老人、孕妇、慢病患者或免疫低下。','已经使用哪些退热药、复方感冒药、止咳药，是否有重复成分。','是否有流感/新冠接触史，是否需要检测、就医或抗病毒药物评估。'],
[('轻症自我照护','鼻塞流涕咽痛轻、精神状态好、无高危因素','说明书教育、补液休息、对症品类咨询','不推荐抗生素，不叠加复方药'),('药师重点判断','发热咳嗽较明显、高风险人群、复方药使用不清','核对成分和人群禁忌，提示检测或就医','不把所有呼吸道症状都当普通感冒'),('优先就医','呼吸困难、胸痛、意识异常、持续高热、婴幼儿或老人明显异常','提示就医','不以送药替代评估')],
[('退热镇痛类','发热、头痛、肌肉酸痛；夜间急用','核对年龄、肝肾风险和重复成分','快速配送但先提示剂量和禁忌'),('鼻塞流涕类','鼻塞、流涕、打喷嚏','高血压、儿童、孕妇等需谨慎','按鼻部症状展示，不等同抗感染'),('止咳祛痰类','咳嗽影响休息','区分干咳、痰多、喘息和呼吸困难','咳喘/胸痛触发就医提醒'),('检测/防护用品','疑似流感/新冠或家庭防护','检测不能替代就医判断','与发热咳嗽入口联动'),('药师咨询','复方药不清、特殊人群、症状反复','核对重复成分和风险','咨询优先于商品堆叠')],
[('平台','呼吸道入口要区分普通感冒、流感和高风险信号，复方感冒药不能默认首推。'),('药店','药师应重点核对复方药成分、特殊人群和呼吸困难等红旗信号。'),('药企','感冒类产品教育应讲清成分、适用症状和禁忌，不能泛化成所有咳嗽发热场景。')])

render('高血压基础概念与慢病复购场景','08-疾病与医学基础/补充资料/高血压基础概念与慢病复购场景.md',
'本文回答：高血压为什么不是一次性买药问题，而是长期血压监测、心脑血管风险控制和慢病复购管理问题。核心判断是：即时零售能提高降压药和血压计可得性，但不能替代医生根据血压、合并症和靶器官损害调整治疗。',
[('高血压：多数时候没有明显症状，但长期风险很高','高血压是以血压长期升高为核心的慢病，很多患者没有明显不适，却会增加卒中、冠心病、心衰、肾病和视网膜病变风险。药店不能只等用户头晕头痛才关注血压。'),('家庭血压与诊室血压：都需要规范测量','家庭血压能帮助观察日常控制情况，诊室血压用于医疗评估。测量姿势、袖带大小、测量时间、是否记录连续数据都会影响判断。平台卖血压计应同时提供测量教育。'),('降压药复购：不断药只是底线，达标和耐受更重要','用户长期复购降压药，需要关注是否按医嘱服用、是否漏服、是否出现头晕低血压、水肿、咳嗽、心率异常等问题。药店不能自行建议停药或换药。'),('合并风险：高血压常与糖尿病、高脂血症、冠心病和肾病共存','合并疾病会改变治疗目标和用药风险。药师咨询应关注用户是否多药联用、是否有肾功能问题、是否同时服用止痛药或保健品。')],
['最近家庭血压和诊室血压是多少，是否连续记录。','是否已有医生诊断和处方，是否规律服药，有无漏服或自行停药。','是否有胸痛、呼吸困难、神经系统症状、意识异常或血压极高。','是否合并糖尿病、高脂血症、冠心病、肾病或正在多药联用。','是否需要血压计、用药提醒、医保复购或药师随访。'],
[('稳定复购','已有诊断和处方，血压记录相对稳定','复购提醒、血压计和记录教育、依从性提醒','不自行调整处方'),('药师重点判断','血压波动、漏服、不良反应或多药联用','核对用药和复诊需求，提醒监测','不替代医生调药'),('优先就医','血压极高伴胸痛、呼吸困难、神经系统症状、意识异常或孕期高血压','提示急诊或就医','不靠平台买药处理')],
[('降压药复购','已有医生处方的长期用药','不自行停药、换药或加量','处方/医保/复购提醒'),('血压计和记录工具','家庭血压管理','教会规范测量和记录趋势','设备销售与教育绑定'),('药师随访','漏服、不良反应、多药联用','提醒复诊和核对相互作用','慢病服务而非单次交易'),('生活方式支持','限盐、体重、运动、戒烟限酒','辅助管理，不替代药物','内容教育和复购提醒结合')],
[('平台','高血压场景应做血压记录、处方复购和风险拦截，不能只做降压药低价补货。'),('药店','药师应围绕测量方法、依从性、不良反应和合并用药服务用户。'),('药企','降压药教育应强调长期达标、依从性和监测，而非单次购买。')])

